#include <iostream>
#include <mutex>
#include <thread>

int main()
{
    int completed{};
    std::mutex mutex;
    auto work = [&] {
        for (int i{}; i < 100; ++i)
        {
            std::lock_guard lock{mutex};
            ++completed;
        }
    };
    {
        std::jthread first{work};
        std::jthread second{work};
    }
    std::cout << completed << '\n';
}
